using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RegionalControlTests
{
    static WorldSession New()=>new(RegionalControl.Create());
    static EntityId Start(WorldSession s){s.Submit(RegionalBranch.Order(s.DiagnosticSnapshot(),"request:move"),s.Revision);s.AdvanceTo(5);return s.DiagnosticSnapshot().Tasks[0].Id;}
    static Intent Send(WorldSession s,EntityId target,ActionKind kind,long effective=11660,bool important=true,string id="request:control"){var i=RegionalControl.Order(s.DiagnosticSnapshot(),id,target,kind,effective,important);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);return i;}
    static void Open(WorldSession s){var m=s.GetActorView(ContractFixture.Officer).Messages.Single(m=>m.Sealed);Assert.Equal(ResultCode.Accepted,s.Open(ContractFixture.Officer,m.Id,s.Revision).Code);}
    [Fact] public void PhysicalReceiptOpeningAndEffectiveTimeRemainDistinct(){var s=New();Send(s,Start(s),ActionKind.Cancel);s.AdvanceTo(20000);Assert.True(s.Paused);Assert.Equal(11656,s.Seconds);Assert.Null(s.GetActorView(ContractFixture.Officer).Messages.Single(m=>m.Sealed).KnownBody);s.SetPaused(false);s.AdvanceTo(11658);Open(s);s.AdvanceTo(11659);Assert.True(s.GetBranchView(ContractFixture.Officer).Walking);s.AdvanceTo(11660);Assert.False(s.GetBranchView(ContractFixture.Officer).Walking);Assert.Equal(11658560,s.GetBranchView(ContractFixture.Officer).DistanceMm);}
    [Fact] public void ReturnFinishesCurrentEdgeThenWalksKnownRouteHome(){var s=New();Send(s,Start(s),ActionKind.Redirect);s.AdvanceTo(11656);Open(s);s.SetPaused(false);s.AdvanceTo(11660);Assert.Equal(31179,s.GetBranchView(ContractFixture.Officer).ArrivalAt);var outbound=s.GetBranchView(ContractFixture.Officer).Heading;s.AdvanceTo(15590);Assert.Equal(RegionalBranch.Nodes.Single(n=>n.Id=="kasadera").Position,s.GetBranchView(ContractFixture.Officer).Position);Assert.True(outbound.EastMm*s.GetBranchView(ContractFixture.Officer).Heading.EastMm<0);s.AdvanceTo(31178);Assert.True(s.GetBranchView(ContractFixture.Officer).Walking);s.AdvanceTo(31179);Assert.Equal(ContractFixture.Castle,s.GetActorView(ContractFixture.Officer).Location.Site);}
    [Fact] public void UnopenedPastEffectiveCommandDoesNotStopOfficer(){var s=New();Send(s,Start(s),ActionKind.Cancel);s.AdvanceTo(11656);s.SetPaused(false);s.AdvanceTo(11670);Assert.True(s.GetBranchView(ContractFixture.Officer).Walking);Open(s);Assert.False(s.GetBranchView(ContractFixture.Officer).Walking);Assert.Equal(11668560,s.GetBranchView(ContractFixture.Officer).DistanceMm);}
    [Fact] public void DeliveryQuoteUsesKnownAppointmentAndPhysicalCourierDistance(){var a=New();var b=New();var ta=Start(a);var tb=Start(b);var wa=a.DiagnosticSnapshot();var wb=b.DiagnosticSnapshot();wb.Branches=wb.Branches! with{BlockedEdges=[]};var x=RegionalControl.Order(wa,"request:x",ta,ActionKind.Cancel);Assert.Equal(11651,x.DeliverySeconds);Assert.Equal(ContractJson.Write(x),ContractJson.Write(RegionalControl.Order(wb,"request:x",tb,ActionKind.Cancel)));Assert.Equal(5828,RegionalControl.CourierToFork(wa));}
    [Fact] public void MissedRendezvousCannotRemotelyDeliverAndFailureIsDelayed(){var s=New();var target=Start(s);s.AdvanceTo(11657);Send(s,target,ActionKind.Cancel);s.AdvanceTo(17485);Assert.DoesNotContain(s.GetActorView(ContractFixture.Officer).Messages,m=>m.Sealed);Assert.DoesNotContain(s.GetActorView(ContractFixture.Lord).Messages,m=>m.KnownBody?.Contains("/attempt/")==true);s.AdvanceTo(23313);Assert.Contains(s.GetActorView(ContractFixture.Lord).Messages,m=>m.KnownBody?.Contains("/attempt/")==true);}
    [Theory][InlineData(ActionKind.Cancel)][InlineData(ActionKind.Redirect)]
    public void SameRequestCannotExecuteAgainAfterOutcome(ActionKind kind){var s=New();var i=Send(s,Start(s),kind);Assert.Equal(ResultCode.AlreadyAccepted,s.Submit(i,s.Revision).Code);s.AdvanceTo(11656);Open(s);s.SetPaused(false);s.AdvanceTo(50000);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.Submit(i,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Single(s.DiagnosticSnapshot().Outbox,o=>o.Task==s.DiagnosticSnapshot().Tasks.Last().Id);}
    [Theory][InlineData(true)][InlineData(false)]
    public void SimultaneousCancelPrecedesRedirectRegardlessOfSubmission(bool cancelFirst){var s=New();var target=Start(s);var a=RegionalControl.Order(s.DiagnosticSnapshot(),"request:cancel",target,ActionKind.Cancel,11660,false);var b=RegionalControl.Order(s.DiagnosticSnapshot(),"request:redirect",target,ActionKind.Redirect,11660,false);foreach(var i in cancelFirst?new[]{a,b}:new[]{b,a})s.Submit(i,s.Revision);s.AdvanceTo(50000);Assert.Equal(ExecutionPhase.Stopped,s.DiagnosticSnapshot().Tasks[0].Execution);Assert.Equal(11658560,s.GetBranchView(ContractFixture.Officer).DistanceMm);}
    [Fact] public void CancelWinsAgainstUncommittedArrivalAtSameSecond(){var s=New();Send(s,Start(s),ActionKind.Cancel,18343);s.AdvanceTo(11656);Open(s);s.SetPaused(false);s.AdvanceTo(18343);Assert.Equal(ExecutionPhase.Stopped,s.DiagnosticSnapshot().Tasks[0].Execution);Assert.DoesNotContain(s.DiagnosticSnapshot().EffectLedger,e=>e.BusinessKey=="task:1/finish/1");}
    [Theory][InlineData(1001)][InlineData(11656)][InlineData(11658)][InlineData(11660)]
    public void SavesRestoreTransitSealedScheduledAndAppliedState(long at){var s=New();Send(s,Start(s),ActionKind.Redirect);s.AdvanceTo(Math.Min(11656,at));if(at>11656){Open(s);s.SetPaused(false);s.AdvanceTo(at);}var root=Path.Combine(Path.GetTempPath(),"hakutai-regional-control-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,RegionalControl.Create().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId,new(.375,60));var load=store.Prepare("test");var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(load,host.Current,host.Current.Revision));Assert.True(host.Current.Paused);Assert.Equal(ContractJson.Write(s.GetBranchView(ContractFixture.Officer)),ContractJson.Write(host.Current.GetBranchView(ContractFixture.Officer)));Assert.Equal(.375,load.Presentation.DisplayFraction);Assert.Equal(60,load.Presentation.DisplaySpeed);foreach(var world in new[]{s,host.Current}){world.SetPaused(false);if(world.Seconds<11656)world.AdvanceTo(11656);if(world.GetActorView(ContractFixture.Officer).Messages.Any(m=>m.Sealed)){world.SetPaused(false);world.AdvanceTo(11658);Open(world);}world.SetPaused(false);world.AdvanceTo(50000);}var a=s.DiagnosticSnapshot();var b=host.Current.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(a.Branches),ContractJson.Write(b.Branches));Assert.Equal(a.EffectLedger,b.EffectLedger);Assert.Equal(a.Messaging.Messages,b.Messaging.Messages);Assert.Equal(a.Locations.Select(l=>l with{Revision=0}),b.Locations.Select(l=>l with{Revision=0}));}
    [Theory][InlineData(ActionKind.Cancel)][InlineData(ActionKind.Redirect)]
    public void LateOriginalAndRetryAtMeetingDoNotDuplicateEffects(ActionKind kind){var s=New();var target=Start(s);Send(s,target,ActionKind.Cancel,11656,false,"request:hold");s.AdvanceTo(7);Send(s,target,kind,id:"request:late");var task=s.DiagnosticSnapshot().Tasks.Last();var mid="message:"+task.Id.Value.Replace(':','/')+"/order";s.DiagnosticTransport((m,_)=>MessageFlow.Fail(m,mid));s.AdvanceTo(17484);s.DiagnosticTransport((m,t)=>{MessageFlow.Retry(m,mid,ContractFixture.Lord.Value,t,1);MessageFlow.ScheduleLate(m,mid,1,t,1);});s.AdvanceTo(17485);Assert.Equal(2,s.DiagnosticSnapshot().Messaging.Attempts.Count(a=>a.MessageId==mid&&a.Status==AttemptStatus.Delivered));Open(s);s.SetPaused(false);s.AdvanceTo(50000);Assert.Single(s.DiagnosticSnapshot().Outbox,o=>o.Task==task.Id);Assert.Equal(RegionalBranch.Nodes.Single(n=>n.Id=="fork").Position,s.GetBranchView(ContractFixture.Officer).Position);}
    [Fact] public void FutureStartMovesAppointmentWithoutLookingUpLivePosition(){var s=New();s.Submit(RegionalBranch.Order(s.DiagnosticSnapshot(),"request:future") with{EffectiveAt=100},s.Revision);s.AdvanceTo(5);var i=Send(s,s.DiagnosticSnapshot().Tasks[0].Id,ActionKind.Cancel);Assert.Equal(11750,i.DeliverySeconds);s.AdvanceTo(11755);Assert.True(s.Paused);Assert.Equal(RegionalBranch.Nodes.Single(n=>n.Id=="fork").Position,s.GetBranchView(ContractFixture.Officer).Position);}
    [Theory][InlineData(ActionKind.Cancel)][InlineData(ActionKind.Redirect)]
    public void OpeningAfterArrivalCannotUndoCommittedCompletion(ActionKind kind){var s=New();Send(s,Start(s),kind);s.AdvanceTo(11656);s.SetPaused(false);s.AdvanceTo(18344);Assert.Equal(ExecutionPhase.Completed,s.DiagnosticSnapshot().Tasks[0].Execution);var at=s.GetBranchView(ContractFixture.Officer).Position;Open(s);Assert.Equal(ExecutionPhase.Completed,s.DiagnosticSnapshot().Tasks[0].Execution);Assert.Equal(at,s.GetBranchView(ContractFixture.Officer).Position);Assert.Single(s.DiagnosticSnapshot().EffectLedger,e=>e.BusinessKey=="task:1/finish/1");}

}
